exploreUrl:
@js:
let list = [];
list.push({"title": "热门排行", "url": "/fictions/sort-read/{{page}}.html"});
list.push({"title": "最近更新", "url": "/fictions/{{page}}.html"});
let html = java.ajax("https://crxs.me/categories.html");
let reg = /href="(\/fictions\/tag-\d+)\.html"[\s\S]*?<div class="title">([^<]+)<\/div>/g;
let match;
while ((match = reg.exec(html)) !== null) {
    list.push({
        "title": match[2],
        "url": match[1] + "/{{page}}.html"
    });
}
JSON.stringify(list);
